import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import ch.jalu.configme.exception.ConfigMeException;
import ch.jalu.configme.properties.Property;

public class PropertyListBuilderTest {

    @Test
    public void addPropertyTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        Property property = Mockito.mock(Property.class);
        Mockito.when(property.getPath()).thenReturn("path.test");
        propertyListBuilder.add(property);
        Map<String, Object> myRootEntries = propertyListBuilder.getRootEntries();
        assertEquals(1, myRootEntries.size());
        assertTrue(myRootEntries.containsKey("path.test"));
    }

    @Test(expected = ConfigMeException.class)
    public void addSamePropertyTwiceTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        Property property = Mockito.mock(Property.class);
        Mockito.when(property.getPath()).thenReturn("path.test");
        propertyListBuilder.add(property);
        propertyListBuilder.add(property);
    }

    @Test
    public void createPropertyListTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        Property property1 = Mockito.mock(Property.class);
        Property property2 = Mockito.mock(Property.class);
        Mockito.when(property1.getPath()).thenReturn("path.test1");
        Mockito.when(property2.getPath()).thenReturn("path.test2");
        propertyListBuilder.add(property1);
        propertyListBuilder.add(property2);
        List<Property<?>> myList = propertyListBuilder.create();
        assertEquals(2, myList.size());
        assertTrue(myList.contains(property1));
        assertTrue(myList.contains(property2));
    }

    @Test
    public void getRootEntriesTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        Map<String, Object> myRootEntries = propertyListBuilder.getRootEntries();
        assertTrue(myRootEntries.isEmpty());
    }
}
